"""Report completed observed-RGB validity diagnostic, retaining all limitations."""
import csv,hashlib,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main():
    repo=Path(__file__).resolve().parents[1];root=repo/'results/motion_observation_guard';status=json.loads((root/'status.json').read_text());job=status['job'];native=root/'native_completed';out=native/f'output/job_{job}'
    proof=json.loads((native/'transfer_integrity.json').read_text());assert proof['native_before_local_native_after_all_match']
    assert all(hashlib.sha256((native/k).read_bytes()).hexdigest()==v['sha256'] for k,v in proof['files'].items())
    s=json.loads((out/'summary.json').read_text());audit=json.loads((out/'independent_audit.json').read_text());assert audit['status']=='PASS' and json.loads((native/'final_audit_receipt.json').read_text())['status']=='COMPLETE_WITH_INDEPENDENT_AUDIT'
    with (out/'paired_guard.csv').open() as f:rows=list(csv.DictReader(f))
    arms=['baseline','unconditional','observed_guard'];labels=['Frozen baseline','Always correct','Observed-input guard'];absolute={};local=[]
    fig,axes=plt.subplots(1,2,figsize=(11.5,4.4),layout='constrained')
    for ax,metric,title in zip(axes,['feature_mse','task_error'],['Complete feature error','Position error']):
        for j,arm in enumerate(arms):
            values=[];errors=[[],[]]
            for h in (3,6):
                rr=[r for r in rows if r['arm']==arm and int(r['horizon'])==h];pairs=sorted({r['pair'] for r in rr});x=np.array([np.mean([float(r['uniform_'+metric]) for r in rr if r['pair']==p]) for p in pairs]);ix=np.random.default_rng(0).integers(0,96,(10000,96));lo,hi=np.quantile(x[ix].mean(1),[.025,.975]);m=float(x.mean());values.append(m);errors[0].append(m-lo);errors[1].append(hi-m);absolute[arm,h,metric]=m
            bars=ax.bar(np.arange(2)+(j-1)*.25,values,.24,color=['.85','.45','.08'][j],edgecolor='black',yerr=errors,capsize=3,label=labels[j]);ax.bar_label(bars,fmt='%.4f',padding=13,fontsize=8)
        ax.set(title=title,ylabel='MSE (lower is better)',xticks=[0,1],xticklabels=['3-step future','6-step future']);ax.margins(y=.30)
    axes[0].legend(fontsize=8,loc='upper center',bbox_to_anchor=(1.1,-.15),ncol=3);fig.suptitle('Does rejecting missing measurements prevent harmful geometric updates?\n96 original validation pairs; all retained sets, seeds and deletion choices included',fontsize=11);fig.savefig(root/'observed_guard.png',dpi=180);plt.close(fig)
    for cell in s['changes']:
        data=[]
        for arm in ('baseline',cell['arm']):
            rr=[r for r in rows if r['arm']==arm and int(r['horizon'])==cell['horizon'] and (cell['seed']=='mean' or int(r['seed'])==cell['seed'])];pp=sorted({r['pair'] for r in rr});data.append(np.array([np.mean([float(r['uniform_'+cell['metric']]) for r in rr if r['pair']==p]) for p in pp]))
        b,x=data;ix=np.random.default_rng(0).integers(0,96,(10000,96));lo,hi=np.quantile((b[ix].mean(1)-x[ix].mean(1))/b[ix].mean(1),[.025,.975]);value=(b.mean()-x.mean())/b.mean();delta=max(abs(value-cell['relative_reduction']),abs(lo-cell['low']),abs(hi-cell['high']));assert delta<1e-12;local.append(delta)
    counts={}
    for arm in arms:
        transfer=[x for x in s['summaries'][arm]['statistics']['oracle_baseline_comparisons'] if x['choice']=='oracle_transfer'];counts[arm]=[sum(x['positive_both_metrics'] for x in transfer),len(transfer)]
    review=dict(status='PASS',incremental_intervals=len(local),max_difference=max(local),cross_horizon_counts=counts,new_GPU=0,Phase1_GO=False)
    (root/'local_statistical_review.json').write_text(json.dumps(review,indent=2)+'\n')
    text=['# Motion: observed-input validity guard','', '## Why this check was needed','', 'The previous geometric correction treated an occluded frame as a position measurement. It helped the prescribed visible pair but harmed arbitrary retained sets. This fixed validation-only experiment asks whether skipping correction for missing visual measurements removes that harm. It borrows the prediction/update separation used in [Kalman object tracking](https://www.mathworks.com/help/vision/ug/using-kalman-filter-for-object-tracking.html); it is not a Kalman implementation or a learned retention policy.','', '## Design and information boundary','', 'Reuse all 96 original validation scene pairs (192 episodes), 3 frozen models, horizons 3 and 6, six clock-only triples and all three deletions. Every outcome retains exactly 2 past observations plus the same 4 recent frames. All 20,736 full baseline vectors and old correction outcomes are cached; there is no predictor/encoder forward, fitting, training, new GPU or test access.','', 'Exactly one rule was frozen before evaluation: apply the old strength-1 correction only if BOTH retained RGB arena crops differ from the CURRENT observed crop; otherwise preserve the baseline exactly. The fixed crop excludes the external distractors. The rule never receives visibility labels, evidence roles, deleted frames or future targets. Labels are used only afterward to explain coverage.','', '**Scope limitation:** this is an RGB-based input check added to a frozen feature predictor, and it exploits this simulator\'s fixed arena/shutter. It is not a general occlusion detector, a representation-only improvement, or independent confirmation. No threshold, crop or strength was changed after seeing new results.','', '## Results: every deletion choice included','', '![Observed-input guard](../results/motion_observation_guard/observed_guard.png)','', 'Lower bars mean smaller error. Error bars are 95% paired-basepair bootstrap intervals (10,000 draws, seed 0), averaging pools, siblings and seeds within each of 96 independent base pairs. These are regression errors, not classification accuracies.','', '| Arm | Feature h3 | Feature h6 | Position h3 | Position h6 |','|---|---:|---:|---:|---:|']
    for arm,label in zip(arms,labels):text.append('|'+label+'|'+'|'.join(f'{absolute[arm,h,m]:.7f}' for m,h in [('feature_mse',3),('feature_mse',6),('task_error',3),('task_error',6)])+'|')
    text+=['','Positive percentages below mean less error than the frozen baseline; negative values indicate harm. All three seeds are retained.','', '| Seed | Horizon | Error | Guard reduction [95%CI] |','|---|---:|---|---:|']
    for c in s['changes']:
        if c['arm']=='observed_guard':text.append(f'|{c["seed"]}|{c["horizon"]}|{c["metric"]}|{100*c["relative_reduction"]:.2f}% [{100*c["low"]:.2f}, {100*c["high"]:.2f}]|')
    text+=['','The fixed guard removes the earlier average regression. Across arbitrary retained sets, mean position error falls about 26–27% and complete-feature error about 1.6–1.8% versus the unchanged predictor. These are incremental validation improvements against the baseline, not the original acceptance comparisons against recent-only/fixed references. All 16 seed/horizon/metric incremental intervals have positive lower bounds; none is a replacement Phase1 gate.','', '## What does the guard actually detect?','', '| Scoring-only visible count | Guard off outcomes | Guard on outcomes |','|---|---:|---:|']
    for k,v in sorted(s['activation_by_scoring_visible_count'].items()):text.append(f'|{k}/2|{v[0]:,}|{v[1]:,}|')
    text+=['', 'These counts include both horizons and three seeds; they are not independent scenes. Any agreement with annotation visibility reflects the known synthetic construction, not real-world detector validation. The inactive arm must equal the baseline exactly, including full vectors.','', '## Deletion-cost diagnostic','', '| Arm | Cross-horizon positive feature-and-position comparisons |','|---|---:|']
    for arm,label in zip(arms,labels):text.append(f'|{label}|{counts[arm][0]}/{counts[arm][1]}|')
    text+=['', 'The oracle chooses a deletion using future-feature error at one horizon and scores it at the other. These shared-data comparisons diagnose score consistency; they are not deployable past-only retention policies, independent datasets or original Phase1 acceptance.','', '## Verification and conclusion boundary','', 'The first independent audit stopped because it promoted the cached float32 baseline to float64 before re-scoring. A separately hashed audit-only fix preserves original per-branch scoring precision. The original failed audit and receipt remain retained; no predictions, guard choices, thresholds or tolerances changed and the primary experiment was not rerun.','',f'Native independent audit: {audit["complete_vectors_recomputed"]:,}full vectors, {audit["observed_decisions_replayed"]:,}observed decisions, {audit["independent_scalar_statistics"]}original scalar statistics and{audit["incremental_statistics"]}incremental intervals. Maximum vector-derived scalar difference{audit["maximum_scalar_difference"]:.3g}; local 32-interval replay maximum{max(local):.3g}. All compact files have matching native-before/local/native-after hashes; large vectors, RGB and raw CSV stay on HPC.','', 'The next bounded step is to lock this exact guard and separately re-evaluate the complete original Motion prediction and deletion tests without another switch or threshold search. Only complete development support could justify fresh independent confirmation. This completes a bounded original-validation diagnosis only. Original Motion 35/51 prediction checks and 8/32 fixed-reference checks remain unchanged; no complete locked test re-evaluation has occurred. Gate stays its separately supported candidate. Overall Phase1_GO remains unestablished and fresh9137 stays closed. No retention policy, retraining or GitHub update. GPU cumulative use is 12,723/28,800 seconds; 16,077 seconds remain.']
    (repo/'docs/MOTION_OBSERVATION_GUARD.md').write_text('\n'.join(text)+'\n');print(json.dumps(review))
if __name__=='__main__':main()
